// Automatisiert aus den Zellkommentaren der offiziellen Excel-Vorlage
// (2016_11_Begutachtungsmodul_Pflegegrade.xltx) extrahiert: Definition je
// Kriterium sowie, wo vorhanden, konkrete Abgrenzungsbeispiele pro
// Selbstaendigkeits-/Haeufigkeitsstufe. Dient als Hilfetext im Wizard, damit
// Nutzer:innen dieselben Maszstaebe anlegen wie ein Gutachter.

export interface QuestionExplanation {
  definition?: string;
  /** Index-aligned mit der jeweiligen 4er-Skala (0-3), falls vorhanden. */
  levels?: (string | null)[];
}

export const QUESTION_EXPLANATIONS: Record<string, QuestionExplanation> = {
  "4.1.1": { definition: "Einnehmen von verschiedenen Positionen im Bett, Drehen um die Längsachse, Aufrichten aus dem Liegen", levels: ["Selbständig ist auch eine Person, die ihre Position unter Nutzung\nvon Hilfsmitteln (Aufrichthilfe, Bettseitenteil, Strickleiter, elektrisch verstellbares Bett) allein verändern kann.", "Die Person kann beispielsweise nach Anreichen eines Hilfsmittels\noder Reichen der Hand ihre Lage im Bett verändern.", "Die Person kann beim Positionswechsel nur wenig mithelfen,\nz. B. auf den Rücken rollen, am Bettgestell festhalten, Aufforderungen folgen wie z. B. „Bitte die Arme vor der Brust verschränken und den Kopf auf die Brust legen.“", "Die Person kann sich beim Positionswechsel nicht oder nur minimal beteiligen."] },
  "4.1.2": { definition: "Sich auf einem Bett, Stuhl oder Sessel aufrecht halten", levels: ["Selbständig ist eine Person auch dann, wenn sie beim Sitzen \ngelegentlich ihre Sitzposition korrigieren muss.", "Die Person kann sich nur kurz, z. B. für die Dauer einer Mahlzeit\noder eines Waschvorgangs, selbständig in der Sitzposition halten, darüber hinaus benötigt sie aber personelle Unterstützung zur Positionskorrektur.", "Die Person kann sich wegen eingeschränkter Rumpfkontrolle auch mit Rücken- und Seitenstütze nicht in aufrechter Position halten und benötigt auch während der Dauer einer Mahlzeit oder eines Waschvorgangs personelle Unterstützung zur Positionskorrektur.", "Die Person kann sich nicht in Sitzposition halten. Bei fehlender Rumpf- und Kopfkontrolle kann die Person nur im Bett oder Lagerungsstuhl liegend gelagert werden."] },
  "4.1.3": { definition: "Von einer erhöhten Sitzfläche, Bettkante, Stuhl, Sessel, Bank, Toilette etc. aufstehen und sich auf einen Rollstuhl, Toilettenstuhl, Sessel o. Ä. umsetzen", levels: ["Selbständig ist jemand auch dann, wenn er keine Personenhilfe\nbenötigt, aber ein Hilfsmittel oder einen anderen Gegenstand\nzum Festhalten oder Hochziehen (z. B. Griffstangen) benutzt oder sich auf Tisch, Armlehnen oder sonstigen Gegenständen abstützen muss, um aufzustehen. Als selbständig ist auch zu bewerten, wer zwar nicht stehen kann, aber sich mit Armkraft ohne personelle Hilfe umsetzen kann (z. B. Bett – Rollstuhl, Rollstuhl – Toilette).", "Die Person kann aus eigener Kraft aufstehen oder sich umsetzen, wenn sie eine Hand oder einen Arm gereicht bekommt.", "Die Pflegeperson muss beim Aufstehen, Umsetzen (erheblichen) Kraftaufwand aufbringen (hochziehen, halten, stützen, heben).\nDie beeinträchtigte Person hilft jedoch in geringem Maße mit, kann z. B. kurzzeitig stehen.", "Die Person muss gehoben oder getragen werden, Mithilfe ist nicht möglich."] },
  "4.1.4": { definition: "Sich innerhalb einer Wohnung oder im Wohnbereich einer Einrichtung zwischen den Zimmern sicher bewegen\n\nAls Anhaltsgröße für übliche Gehstrecken innerhalb einer Wohnung werden mindestens acht Meter festgelegt.\nDie Fähigkeiten zur räumlichen Orientierung und zum Treppensteigen sind unter Punkt F 4.2.2 bzw. Punkt F 4.1.5 zu berücksichtigen.", levels: ["Die Person kann sich ohne Hilfe durch andere Personen fortbewegen.\nDies kann ggf. unter Nutzung von Hilfsmitteln, z. B. Rollator, Rollstuhl oder sonstigen Gegenständen, z. B. Stock oder Möbelstück, geschehen.", "Die Person kann die Aktivität überwiegend selbständig durchführen.\nPersonelle Hilfe ist beispielsweise erforderlich im Sinne\nvon Bereitstellen von Hilfsmitteln (z. B. Rollator oder Gehstock),\nBeobachtung aus Sicherheitsgründen oder gelegentlichem Stützen, Unterhaken.", "Die Person kann nur wenige Schritte gehen oder sich mit dem Rollstuhl nur wenige Meter fortbewegen oder kann nur mit Stützung oder Festhalten einer Pflegeperson gehen.\nDie ausschließliche Fähigkeit der Fortbewegung durch Krabbeln oder Robben ist generell als „überwiegend unselbständig“ zu bewerten.", "Die Person muss gehoben oder getragen werden, Mithilfe ist nicht möglich."] },
  "4.1.5": { definition: "Überwinden von Treppen zwischen zwei Etagen\n\nTreppensteigen ist unabhängig von der individuellen Wohnsituation zu bewerten.", levels: ["Die Person kann ohne Hilfe durch andere Personen in aufrechter Position eine Treppe steigen.", "Die Person kann eine Treppe alleine steigen, benötigt aber Begleitung wegen eines Sturzrisikos.", "Treppensteigen ist nur mit Stützen oder Festhalten der Person\nmöglich.", "Person muss getragen oder mit Hilfsmitteln transportiert werden, keine Eigenbeteiligung."] },
  "4.2.1": { definition: "Fähigkeit, Personen aus dem näheren Umfeld wiederzuerkennen, d. h. Menschen, zu denen im Alltag regelmäßig ein direkter Kontakt besteht.\nDazu gehören z. B. Familienmitglieder, Nachbarn, aber auch Pflegekräfte eines ambulanten Dienstes oder einer stationären Pflegeeinrichtung.", levels: ["Die Person erkennt andere Personen aus ihrem näheren\nUmfeld unmittelbar.", "Die Person erkennt bekannte Personen beispielsweise\nerst nach einer längeren Zeit des Kontaktes in einem\nGespräch oder sie hat Schwierigkeiten, wenn auch\nnicht täglich, aber doch in regelmäßigen Abständen,\nvertraute Personen zu erkennen.", "Die aus dem näheren Umfeld stammenden Personen werden nur selten erkannt oder die Fähigkeit hängt ggf. von der Tagesform ab, d. h. die Fähigkeit unterliegt im Zeitverlauf erheblichen Schwankungen.", "Auch Familienmitglieder werden nicht oder nur ausnahmsweise\nerkannt."] },
  "4.2.2": { definition: "Fähigkeit, sich in der räumlichen Umgebung zurechtzufinden, andere Orte gezielt anzusteuern und zu wissen, wo man sich befindet.", levels: ["Die Person weiß, in welcher Stadt, auf welchem Stockwerk\nund ggf. in welcher Einrichtung sie sich befindet.\nSie kennt sich in den regelmäßig genutzten Räumlichkeiten\naus.\n\nEin Verirren in den Räumlichkeiten der eigenen Wohnung\noder unmittelbar im Wohnbereich einer Einrichtung\nkommt nicht vor und die Person findet sich auch\nin der näheren außerhäuslichen Umgebung zurecht.\nSie weiß beispielsweise, wie sie zu benachbarten Geschäften,\nzu einer Bushaltestelle oder zu einer anderen nahe\ngelegenen Örtlichkeit gelangt.", "Es bestehen Schwierigkeiten, sich in der außerhäuslichen\nUmgebung zu orientieren, beispielsweise nach Verlassendes Hauses wieder den Weg zurückzufinden. In den eigenen Wohnräumen existieren solche Schwierigkeiten hingegen nicht.", "Die Person hat auch in einer gewohnten Wohnumgebung\nSchwierigkeiten, sich zurechtzufinden. Regelmäßig genutzte Räumlichkeiten und Wege in der Wohnumgebung werden nicht immer erkannt.", "Selbst in der eigenen Wohnumgebung ist die Person regelmäßig auf Unterstützung angewiesen, um sich zurechtzufinden."] },
  "4.2.3": { definition: "Fähigkeit, zeitliche Strukturen zu erkennen.\n\nDazu gehören Uhrzeit, Tagesabschnitte (Vormittag, Nachmittag, Abend etc.), Jahreszeiten und die zeitliche Abfolge des eigenen Lebens. Aufschluss über die Fähigkeit zur zeitlichen Orientierung geben Antworten auf die Frage nach der Jahreszeit, dem Jahr, dem Wochentag, dem Monat oder der Tageszeit.", levels: ["Die zeitliche Orientierung ist ohne nennenswerte Beeinträchtigungen\nvorhanden.", "Die Person ist die meiste Zeit über zeitlich orientiert, aber nicht durchgängig. Sie hat z. B. Schwierigkeiten, ohne äußere Orientierungshilfen (Uhr, Dunkelheit etc.) den Tagesabschnitt zu bestimmen.", "Die zeitliche Orientierung ist die meiste Zeit nur in Ansätzen vorhanden. Die Person ist auch unter Nutzung äußerer Orientierungshilfen zumeist nicht in der Lage, Tageszeiten zu erkennen, zu denen regelmäßig bestimmte Ereignisse stattfinden (z. B. Mittagessen).", "Das Verständnis für zeitliche Strukturen und Abläufe ist kaum oder nicht vorhanden."] },
  "4.2.4": { definition: "Fähigkeit, sich an kurz und auch länger zurückliegende Ereignisse oder Beobachtungen zu erinnern.\n\nDazu gehört, dass die Person z. B. weiß, was sie zum Frühstück gegessen hat oder mit welchen Tätigkeiten sie den Vormittag verbracht hat. Im Hinblick auf das Langzeitgedächtnis geht es bei Erwachsenen z. B. um die Kenntnis des Geburtsjahres, des Geburtsorts oder wichtiger Bestandteile des Lebensverlaufs wie Eheschließung und Berufstätigkeit.", levels: ["Die Person kann über kurz zurückliegende Ereignisse\nAuskunft geben oder durch Handlungen und Gesten\nsignalisieren, dass sie sich erinnert.", "Die Person hat Schwierigkeiten, sich an manche kurz\nzurückliegende Ereignisse zu erinnern, oder muss hierzu länger nachdenken, sie hat aber keine nennenswerten Probleme, sich an Ereignisse aus der eigenen Lebensgeschichte zu erinnern.", "Die Person vergisst kurz zurückliegende Ereignisse häufig. Nicht alle, aber wichtige Ereignisse aus der eigenen Lebensgeschichte sind (noch) präsent.", "Die Person ist nicht (oder nur selten) in der Lage, sich an Ereignisse, Dinge oder Personen aus der eigenen Lebensgeschichte zu erinnern."] },
  "4.2.5": { definition: "Fähigkeit, zielgerichtete Handlungen des Lebensalltags, die eine Abfolge von Teilschritten umfassen, zu steuern.\n\nDie Betonung liegt in diesem Fall auf dem Begriff Alltagshandlungen. Gemeint sind zielgerichtete Handlungen, die diese Person täglich oder nahezu täglich im Lebensalltag durchführt oder durchgeführt hat, wie z. B. das komplette Ankleiden, Kaffeekochen oder Tischdecken.", levels: ["Die Person ist in der Lage, die erforderlichen Handlungsschritte\nselbständig in der richtigen Reihenfolge\nauszuführen oder zu steuern, so dass das angestrebte\nErgebnis der Handlung erreicht wird.", "Die Person verliert manchmal den Faden und vergisst, welcher Handlungsschritt der nächste ist. Erhält sie dabei eine Erinnerungshilfe, kann sie die Handlung aber selbständig fortsetzen.", "Die Person hat erhebliche Schwierigkeiten. Sie verwechselt regelmäßig die Reihenfolge der einzelnen Handlungsschritte oder vergisst einzelne, notwendige Handlungsschritte.", "Mehrschrittige Alltagshandlungen werden erst gar nicht begonnen oder nach den ersten Versuchen aufgegeben."] },
  "4.2.6": { definition: "Fähigkeit, folgerichtige und geeignete Entscheidungen im Alltag zu treffen.\n\nDazu gehört z. B. die dem Wetter angepasste Auswahl von Kleidung, die Entscheidung über die Durchführung von Aktivitäten wie Einkaufen, Familienangehörige oder Freunde anrufen, einer Freizeitbeschäftigung nachgehen.\n\nZu klären ist hier die Frage, ob die Entscheidungen folgerichtig sind, d. h. geeignet sind, das angestrebte Ziel zu erreichen oder ein gewisses Maß an Sicherheit und Wohlbefinden oder Bedürfnisbefriedigung zu gewährleisten, z. B. warme Kleidung.", levels: ["Die Person kann auch in unbekannten Situationen\nfolgerichtige Entscheidungen treffen, beispielsweise\nbeim Umgang mit unbekannten Personen, die an der\nHaustür klingeln.", "Im Rahmen der Alltagsroutinen oder in zuvor besprochenen\nSituationen können Entscheidungen getroffen werden, die Person hat aber Schwierigkeiten in unbekannten Situationen.", "Die Person trifft zwar Entscheidungen, diese Entscheidungen sind jedoch in der Regel nicht geeignet, ein bestimmtes Ziel zu erreichen. Dies ist beispielsweise der Fall, wenn die Person mit nur leichter Bekleidung bei winterlichen Temperaturen im Freien spazieren gehen will. Weiterhin liegt eine schwere Beeinträchtigung vor, wenn die Person nur mit Unterstützung in Form von Anleitung, Aufforderung, Aufzeigen von Handlungsalternativen in der Lage ist, Entscheidungen zu treffen.", "Die Person kann Entscheidungen auch mit Unterstützung nicht mehr oder nur selten treffen. Sie zeigt keine deutbare Reaktion auf das Angebot mehrerer Entscheidungsalternativen."] },
  "4.2.7": { definition: "Fähigkeit, Sachverhalte zu verstehen und Informationen inhaltlich einordnen zu können\n\nHier geht es um Ereignisse und Inhalte, die Bestandteil des Alltagslebens der meisten Menschen sind. Gemeint ist etwa die Fähigkeit, zu erkennen, dass man sich in einer bestimmten Situation befindet, z. B. gemeinschaftliche Aktivitäten mit anderen Menschen, Versorgung durch eine Pflegekraft, MDK-Begutachtung sowie die Fähigkeit, Informationen zum Tagesgeschehen aus den Medien, z. B. Fernsehgerät, Tageszeitung, aufzunehmen und inhaltlich zu verstehen. Gleiches gilt für mündlich von anderen Personen übermittelte Informationen.", levels: ["Die Person kann Sachverhalte und Informationen aus\ndem Alltagsleben ohne nennenswerte Probleme verstehen.", "Die Person kann auch einfache Informationen häufig nur nachvollziehen, wenn sie wiederholt erklärt werden. Eine schwere Beeinträchtigung liegt auch dann vor, wenn das Verständnis sehr stark von der Tagesform abhängt.", "Die Person kann auch einfache Informationen häufig nur nachvollziehen, wenn sie wiederholt erklärt werden. Eine schwere Beeinträchtigung liegt auch dann vor, wenn das Verständnis sehr stark von der Tagesform abhängt.", "Die Person gibt weder verbal noch nonverbal zu erkennen,\ndass sie Situationen und übermittelte Informationen verstehen kann."] },
  "4.2.8": { definition: "Fähigkeit, Risiken und Gefahren zu erkennen.\n\nDazu gehören Gefahren wie Strom- und Feuerquellen, Barrieren und Hindernisse auf dem Fußboden bzw. auf Fußwegen, eine problematische Beschaffenheit des Bodens (z. B. Glätte) oder\nGefahrenzonen in der außerhäuslichen Umgebung (z. B. verkehrsreiche Straßen, Baustellen).", levels: ["Die Person kann solche Risiken und Gefahrenquellen\nim Alltagsleben ohne weiteres erkennen, auch wenn\nsie ihnen aus anderen Gründen (z. B. aufgrund von\nsomatischen Beeinträchtigungen) nicht aus dem Weg\ngehen kann.", "Die Person erkennt meist nur solche Risiken und Gefahren,\ndie sich in der vertrauten innerhäuslichen Wohnumgebung\nwiederfinden. Es bestehen aber beispielsweise Schwierigkeiten, Risiken im Straßenverkehr angemessen einzuschätzen oder Gefährdungen in ungewohnter Umgebung zu erkennen.", "Die Person kann auch Risiken und Gefahren, denen sie häufig auch in der Wohnumgebung begegnet, oft nicht als solche erkennen.", "Die Person kann Risiken und Gefahren so gut wie gar nicht erkennen."] },
  "4.2.9": { definition: "Fähigkeit, elementare Bedürfnisse verbal oder nonverbal mitzuteilen.\n\nDas beinhaltet, sich bei Hunger oder Durst, Schmerzen oder Frieren bemerkbar zu machen. Bei Sprachstörungen kann dies ggf. durch Laute, Mimik oder Gestik bzw. unter Nutzung von Hilfsmitteln erfolgen.", levels: ["Die Person kann Bedürfnisse äußern.", "Die Person kann auf Nachfrage elementare Bedürfnisse\näußern. Die Person äußert Bedürfnisse aber nicht immer von sich aus.", "Elementare Bedürfnisse sind nur aus nonverbalen Reaktionen (Mimik, Gestik, Lautäußerungen) ableitbar, ggf. nach oder durch entsprechende(r) Stimulation; oder die Person äußert von sich aus keine elementaren Bedürfnisse, muss dazu ständig angeleitet werden, kann aber Zustimmung oder Ablehnung deutlich machen.", "Die Person äußert nicht oder nur sehr selten Bedürfnisse, auch nicht in nonverbaler Form. Sie kann weder Zustimmung noch Ablehnung deutlich machen."] },
  "4.2.10": { definition: "Fähigkeit, Aufforderungen in Hinblick auf alltägliche Grundbedürfnisse zu verstehen.\n\nZu den alltäglichen Grundbedürfnissen gehören z. B. Essen, Trinken, sich kleiden, sich beschäftigen.", levels: ["Aufforderungen und Bitten zu alltäglichen Grundbedürfnissen\nwerden ohne weiteres verstanden.", "Einfache Bitten und Aufforderungen, wie z. B. „Setz dich bitte an den Tisch!“, „Zieh dir die Jacke über!“, „Komm zum Essen!“, „Prosit!“ werden verstanden, Aufforderungen in nicht alltäglichen Situationen müssen erklärt werden.\nGgf. sind besonders deutliche Ansprache, Wiederholungen,\nZeichensprache, Gebärdensprache oder Schrift erforderlich, um Aufforderungen verständlich zu machen.", "Die Person kann Aufforderungen und Bitten meist nicht verstehen, wenn diese nicht wiederholt geäußert und erläutert werden. Das Verständnis ist sehr von der Tagesform abhängig. Sie zeigt aber Zustimmung oder Ablehnung gegenüber nonverbalen Aufforderungen, z. B. Berührungen oder Geleiten an den Esstisch.", "Die Person kann Anleitungen und Aufforderungen kaum oder nicht verstehen."] },
  "4.2.11": { definition: "Fähigkeit, in einem Gespräch Gesprächsinhalte aufzunehmen, sinngerecht zu antworten und zur Weiterführung des Gesprächs Inhalte einzubringen.", levels: ["Die Person kommt sowohl in Einzel- als auch in Gesprächen\nkleiner Gruppen gut zurecht. Sie zeigt im Gespräch\nEigeninitiative, Interesse und beteiligt sich, wenn vielleicht\nauch nur auf direkte Ansprache hin. Ihre Äußerungen\npassen zu den Inhalten des Gesprächs.", "Die Person kommt in Gesprächen mit einer Person gut zurecht, in Gruppen ist sie jedoch meist überfordert und verliert den Faden. Wortfindungsstörungen treten ggf. regelmäßig auf. Die Person ist häufig auf besonders deutliche Ansprache oder Wiederholung von Worten, Sätzen angewiesen.", "Die Person kann auch einem Gespräch nur mit einer Person kaum folgen oder sie kann sich nur wenig oder mit einzelnen Worten beteiligen.\nDie Person zeigt nur wenig Eigeninitiative, reagiert aber auf Ansprache oder Fragen mit wenigen Worten, z. B. mit ja oder nein; die Person beteiligt sich am Gespräch, weicht aber in aller Regel vom Gesprächsinhalt ab (führt mehr ein Selbstgespräch) oder es besteht leichte Ablenkbarkeit durch Umgebungseinflüsse.", "Ein Gespräch mit der Person, das über einfache Mitteilungen\nhinausgeht, ist auch unter Einsatz nonverbaler Kommunikation kaum oder nicht möglich."] },
  "4.3.1": { definition: "Dieses Kriterium fasst verschiedene Verhaltensweisen zusammen. Dazu gehören vor allem das (scheinbar) ziellose Umhergehen in der Wohnung oder der Einrichtung und der Versuch desorientierter Personen, ohne Begleitung die Wohnung, Einrichtung zu verlassen oder Orte aufzusuchen, die für diese Person unzugänglich sein sollten, z. B. Treppenhaus, Zimmer anderer Bewohner.\nEbenso zu berücksichtigen ist allgemeine Rastlosigkeit in Form von ständigem Aufstehen und Hinsetzen oder Hin- und Herrutschen auf dem Sitzplatz oder im und aus dem Bett." },
  "4.3.2": { definition: "Gemeint sind hier nächtliches Umherirren oder nächtliche Unruhephasen bis hin zur Umkehr des Tag-Nacht-Rhythmus im Sinne von aktiv sein in der Nacht und schlafen während des Tages.\nZu bewerten ist, wie häufig Anlass für personelle Unterstützung zur Steuerung des Schlaf-Wach-Rhythmus besteht, z. B. wieder ins Bett bringen und beruhigen. Schlafstörungen wie Einschlafschwierigkeiten am Abend oder Wachphasen während der Nacht sind nicht zu werten. Andere nächtliche Hilfen, z. B. Aufstehen, zu Bett bringen bei Nykturie oder Lagerungen sind nur unter F 4.6.2. zu werten." },
  "4.3.3": { definition: "Selbstschädigendes und autoaggressives Verhalten kann z. B. darin bestehen, sich selbst durch Gegenstände zu verletzen, ungenießbare Substanzen zu essen und zu trinken, sich selbst zu schlagen und sich selbst mit den Fingernägeln oder Zähnen zu verletzen." },
  "4.3.4": { definition: "Gemeint sind hier aggressive auf Gegenstände gerichtete Handlungen wie Gegenstände wegstoßen oder wegschieben, gegen Gegenstände schlagen, das Zerstören von Dingen sowie das Treten nach Gegenständen." },
  "4.3.5": { definition: "Physisch aggressives Verhalten gegenüber anderen Personen kann z. B. darin bestehen, nach Personen zu schlagen oder zu treten, andere mit Zähnen oder Fingernägeln zu verletzen, andere zu stoßen oder wegzudrängen, oder in Verletzungsversuchen gegenüber anderen Personen mit Gegenständen." },
  "4.3.6": { definition: "Verbale Aggression kann sich z. B. in verbalen Beschimpfungen oder in der Bedrohung anderer Personen ausdrücken." },
  "4.3.7": { definition: "Andere pflegerelevante vokale Auffälligkeiten können sein: Lautes Rufen, Schreien, Klagen ohne nachvollziehbaren Grund, vor sich hin schimpfen, fluchen, seltsame Laute von sich geben,\nständiges Wiederholen von Sätzen und Fragen." },
  "4.3.8": { definition: "Hier ist die Abwehr von Unterstützung, z. B. bei der Körperpflege, die Verweigerung der Nahrungsaufnahme, der Medikamenteneinnahme oder anderer notwendiger Verrichtungen sowie die Manipulation an Vorrichtungen wie z. B. an Kathetern, Infusionen oder Sondenernährung gemeint. Dazu gehört nicht die willentliche (selbstbestimmte) Ablehnung bestimmter Maßnahmen." },
  "4.3.9": { definition: "Wahnvorstellungen beziehen sich z. B. auf die Vorstellung, mit Verstorbenen oder imaginären Personen in Kontakt zu stehen, oder auf die Vorstellung, verfolgt, bedroht oder bestohlen zu\nwerden." },
  "4.3.10": { definition: "Die Person hat starke Ängste oder Sorgen, sie erlebt Angstattacken unabhängig von der Ursache." },
  "4.3.11": { definition: "Antriebslosigkeit bei depressiver Stimmungslage zeigt sich z. B. daran, dass die Person kaum Interesse an der Umgebung hat, kaum Eigeninitiative aufbringt und Motivierung durch andere\nbenötigt, um etwas zu tun. Sie wirkt traurig oder apathisch, möchte am liebsten das Bett nicht verlassen. Hier ist nicht gemeint, dass Menschen mit rein kognitiven Beeinträchtigungen, z. B. bei Demenz, Impulse benötigen, um eine Handlung zu beginnen oder fortzuführen." },
  "4.3.12": { definition: "Sozial inadäquate Verhaltensweisen sind z. B. distanzloses Verhalten, auffälliges Einfordern von Aufmerksamkeit, sich vor anderen in unpassenden Situationen auszukleiden, unangemessenes Greifen nach Personen oder unangemessene körperliche oder verbale sexuelle Annäherungsversuche." },
  "4.3.13": { definition: "Sonstige pflegerelevante inadäquate Handlungen sind z. B. Nesteln an der Kleidung, ständiges Wiederholen der gleichen Handlung (Stereotypien), planlose Aktivitäten, Verstecken oder Horten von Gegenständen, Kotschmieren, Urinieren in die Wohnung." },
  "4.4.1": { definition: "Sich die Hände, das Gesicht, den Hals, die Arme, die Achselhöhlen und den vorderen Brustbereich waschen und abtrocknen.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann die Aktivität selbständig durchführen, wenn benötigte Gegenstände, z. B. Seife, Waschlappen, bereitgelegt werden oder sie Aufforderung bzw. punktuelle Teilhilfen, z. B. Waschen unter den Achseln oder der Brust, erhält.", "Die Person kann nur geringe Anteile der Aktivität selbständig durchführen, sich z. B. nur Hände oder Gesicht waschen, oder benötigt umfassende Anleitung.", "Die Person kann sich an der Aktivität nicht oder nur minimal beteiligen."] },
  "4.4.2": { definition: "Kämmen, Zahnpflege, Prothesenreinigung, Rasieren.", levels: ["Die Person kann die beschriebene Aktivitäten ohne personelle Hilfe durchführen.", "Die Person kann die Aktivitäten selbständig durchführen, wenn benötigte Gegenstände bereitgelegt oder gerichtet werden, z. B. Aufdrehen der Zahnpastatube, Auftragen der Zahnpasta auf die Bürste, Aufbringen von Haftcreme auf die Prothese, Anreichen oder Säubern des Rasierapparates. Alternativ sind Aufforderungen oder punktuelle Teilhilfen erforderlich wie Korrekturen nach dem Kämmen oder nur das Kämmen des Hinterkopfes, das Reinigen der hinteren Backenzähne bei der Zahn-, Mundpflege bzw. die Nachrasur bei sonst selbständigem Rasieren.", "Die Person kann nur geringe Anteile der Aktivität selbständig leisten, so beginnt sie z. B. mit dem Zähneputzen oder der Rasur, ohne die Aktivität zu Ende zu führen.", "Die Person kann sich an den Aktivitäten nicht oder nur minimal beteiligen."] },
  "4.4.3": { definition: "Den Intimbereich waschen und abtrocknen.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann die Aktivität selbständig durchführen, wenn benötigte Utensilien, z. B. Seife, Waschlappen, bereitgelegt werden oder sie Aufforderung bzw. punktuelle Teilhilfen erhält.", "Die Person kann nur geringe Anteile der Aktivität selbständig durchführen, sich z. B. nur den vorderen Intimbereich waschen.", "Die Person kann sich an der Aktivität nicht oder nur minimal beteiligen."] },
  "4.4.4": { definition: "Durchführung des Dusch- oder Wannenbades einschließlich des Waschens der Haare.\n\nDabei sind neben der Fähigkeit, den Körper waschen zu können, auch Sicherheitsaspekte zu berücksichtigen. (Teil-)Hilfen beim Waschen in der Wanne, Dusche sind hier ebenso zu berücksichtigen wie die Hilfe beim Ein- und Aussteigen oder eine notwendige Überwachung während des Bades. Dazu gehört auch das Abtrocknen, Haare waschen und föhnen.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann die Aktivität selbständig durchführen, wenn Utensilien vorbereitet bzw. bereitgestellt werden, einzelne Handreichungen geleistet werden, z. B. Stützen beim Ein-, Aussteigen, Bedienung eines Badewannenlifters, Hilfe beim Haarewaschen oder Föhnen, beim Abtrocknen, oder wenn während des (Dusch-)Bades aus nachvollziehbaren Sicherheitsgründen Anwesenheit erforderlich ist.", "Die Person kann nur einen begrenzten Teil der Aktivität selbständig durchführen, z. B. das Waschen des vorderen Oberkörpers.", "Die Person kann sich an der Aktivität nicht oder nur minimal beteiligen."] },
  "4.4.5": { definition: "Bereitliegende Kleidungsstücke, z. B. Unterhemd, T-Shirt, Hemd, Bluse, Pullover, Jacke, BH, Schlafanzugoberteil oder Nachthemd, an- und ausziehen.\n\nDie Beurteilung ist unabhängig davon vorzunehmen, ob solche Kleidungsstücke derzeit getragen werden. Die situationsgerechte Auswahl der Kleidung ist nicht hier, sondern unter Punkt F 4.2.6 zu berücksichtigen. Das An- und Ablegen von körpernahen Hilfsmitteln ist unter Punkt F 4.5.7 zu berücksichtigen.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann die beschriebene Aktivität ohne personelle Hilfe\ndurchführen.", "Die Person kann nur bei einem begrenzten Teil der Aktivität mithelfen, beispielsweise die Hände in die Ärmel eines bereitgehaltenen T-Shirts schieben.", "Die Person kann sich an der Aktivität nicht oder nur minimal beteiligen."] },
  "4.4.6": { definition: "Bereitliegende Kleidungsstücke, z. B. Unterwäsche, Hose, Rock, Strümpfe und Schuhe, an- und ausziehen.\n\nDie Beurteilung ist unabhängig davon vorzunehmen, ob solche Kleidungsstücke derzeit getragen werden. Die situationsgerechte Auswahl der Kleidung ist unter Punkt F 4.2.6 zu berücksichtigen. Das An- und Ablegen von körpernahen Hilfsmitteln ist unter Punkt F 4.5.7 zu berücksichtigen, z. B. Kompressionsstrümpfe.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe\n durchführen.", "Die Person kann die Aktivität beispielsweise selbständig durchführen, wenn Kleidungsstücke angereicht oder gehalten werden (Einstiegshilfe). Auch wenn Hilfe nur bei Verschlüssen, z. B. Schnürsenkel binden, Knöpfe schließen oder Kontrolle des Sitzes der Kleidung, und Aufforderungen zur Vervollständigung der Handlung erforderlich sind, trifft die Bewertung „überwiegend selbständig“ zu.", "Die Person kann die Aktivität zu einem geringen Teil selbständig durchführen. Beispielsweise gelingt das Hochziehen von Hose, Rock zur Taille selbständig, zuvor muss das Kleidungsstück jedoch von der Pflegeperson über die Füße gezogen werden.1", "Die Person kann sich an der Aktivität nicht oder nur minimal beteiligen."] },
  "4.4.7": { definition: "Zerteilen von Nahrung in mundgerechte Stücke und Eingießen von Getränken.\n\nDazu gehört das Zerteilen von belegten Brotscheiben, Obst oder anderen Speisen in mundgerechte Stücke, z. B. das Kleinschneiden von Fleisch, das Zerdrücken von Kartoffeln, Pürieren der Nahrung, Verschlüsse von Getränkeflaschen öffnen, Getränke aus einer Flasche oder Kanne in ein Glas bzw. eine Tasse eingießen, ggf. unter Nutzung von Hilfsmitteln wie Antirutschbrett oder sonstigen Gegenständen wie Spezialbesteck.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Es ist punktuelle Hilfe erforderlich, z. B. beim Öffnen einer Flasche oder beim Schneiden von harten Nahrungsmitteln.", "Die Person kann die Aktivität zu einem geringen Teil selbständig durchführen, beispielsweise schneidet sie zwar belegte Brotscheiben, schafft es aber nicht, mundgerechte Stücke herzustellen. Oder sie gießt aus einer Flasche Wasser ins Glas, verschüttet das Wasser dabei jedoch regelmäßig.", "Die Person kann sich an der Aktivität nicht oder nur minimal beteiligen."] },
  "4.4.8": { definition: "Bereitgestellte, mundgerecht zubereitete Speisen essen.\n\nDies beinhaltet das Aufnehmen, Zum-Mund-Führen, ggf. Abbeißen, Kauen und Schlucken von mundgerecht zubereiteten Speisen, die üblicherweise mit den Fingern gegessen werden, z. B. Brot, Kekse, Obst oder das Essen mit Gabel oder Löffel, ggf. mit speziellen Hilfsmitteln wie adaptiertem Besteck.\nZu berücksichtigen ist auch, inwieweit die Notwendigkeit der ausreichenden Nahrungsaufnahme (auch ohne Hungergefühl oder Appetit) erkannt und die empfohlene, gewohnte Menge tatsächlich gegessen wird.\n\nDas Einhalten von Diäten ist nicht hier, sondern unter Punkt F 4.5.16 zu bewerten.\n\nDie Beurteilung ist auch dann vorzunehmen, wenn die Nahrungsaufnahme über eine Sonde bzw. parenteral erfolgt.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann überwiegend selbständig essen, benötigt aber punktuelle Anleitung, muss beispielsweise aufgefordert werden, mit dem Essen zu beginnen oder weiterzuessen. Es sind punktuelle Hilfen erforderlich, z. B. Zurücklegen aus der Hand gerutschter Speisen oder Besteck in die Hand geben.", "Es muss ständig zur Nahrungsaufnahme motiviert werden oder die Nahrung muss größtenteils gereicht werden oder es ist ständige und unmittelbare Eingreifbereitschaft der Pflegeperson erforderlich, aufgrund von Aspirationsgefahr.", "Die Nahrung muss (nahezu) komplett gereicht werden."] },
  "4.4.9": { definition: "Bereitstehende Getränke aufnehmen, ggf. mit Gegenständen wie Strohhalm, Spezialbecher mit Trinkaufsatz.\n\nZu berücksichtigen ist auch, inwieweit die Notwendigkeit der Flüssigkeitsaufnahme (auch ohne ausreichendes Durstgefühl) erkannt und die empfohlene oder gewohnte Menge tatsächlich getrunken wird.\nDie Beurteilung der Selbständigkeit ist auch dann vorzunehmen, wenn die Flüssigkeitsaufnahme über eine Sonde bzw. parenteral erfolgt.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe\n durchführen.", "Die Person kann selbständig trinken, wenn ein Glas, eine Tasse unmittelbar in den Aktionsradius der Person positioniert oder sie ans Trinken erinnert wird.", "Das Trinkgefäß muss beispielsweise in die Hand gegeben werden, das Trinken erfolgt jedoch selbständig, oder die Person muss zu fast jedem Schluck motiviert werden oder es ist ständige und unmittelbare Eingreifbereitschaft der Pflegeperson erforderlich, aufgrund von Aspirationsgefahr.", "Getränke müssen (nahezu) komplett gereicht werden."] },
  "4.4.10": { definition: "Gehen zur Toilette, Hinsetzen und Aufstehen, Sitzen während der Blasen- oder Darmentleerung, Intimhygiene und Richten der Kleidung.\n\nDie Beurteilung ist auch dann vorzunehmen, wenn anstelle der Toilettenbenutzung eine Versorgung mit Hilfsmitteln erfolgt, z. B. Inkontinenzmaterial, Katheter, Urostoma, Ileo- oder Colostoma.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe durchführen.", "Die Person kann die Aktivität überwiegend selbständig durchführen.\nPersonelle Hilfe kann sich beispielsweise beschränken auf einzelne Handlungsschritte wie:\n• nur Bereitstellen und Leeren des Toilettenstuhls (alternativ Urinflasche oder anderer Behälter),\n• nur Aufforderung oder Orientierungshinweise zum Auffinden der Toilette oder Begleitung auf dem Weg zur Toilette,\n• nur Anreichen von Toilettenpapier oder Waschlappen, Intimhygiene nur nach Stuhlgang,\n• nur Unterstützung beim Hinsetzen, Aufstehen von der Toilette,\n• nur punktuelle Hilfe beim Richten der Bekleidung.", "Die Person kann nur einzelne Handlungsschritte selbst ausführen, z. B. nur Richten der Bekleidung oder Intimhygiene nur nach Wasserlassen.", "Die Person kann sich nicht oder nur minimal an der Aktivität beteiligen."] },
  "4.4.11": { definition: "Inkontinenz- und Stomasysteme sachgerecht verwenden, nach Bedarf wechseln und entsorgen.\n\nDazu gehört auch das Entleeren eines Urinbeutels bei Dauerkatheter, Urostoma oder die Anwendung eines Urinalkondoms.\nDie regelmäßige Einmalkatheterisierung ist nicht hier, sondern unter Punkt F 4.5.10 zu erfassen.", levels: ["Die Person kann Hilfsmittel selbständig benutzen.", "Die Person kann die Aktivität überwiegend selbständig durchführen, wenn Inkontinenzsysteme angereicht oder entsorgt werden oder die Person an den Wechsel erinnert wird.", "Die Person kann sich am Wechsel der Inkontinenzsysteme beteiligen, z. B. nur Vorlagen einlegen oder Inkontinenzhosen nur entfernen.", "Beteiligung ist nicht oder nur minimal möglich."] },
  "4.4.12": { definition: "Inkontinenz- und Stomasysteme sachgerecht verwenden, nach Bedarf wechseln und entsorgen.\n\nDazu gehört, Inkontinenzsysteme, z. B. große Vorlagen mit Netzhose, Inkontinenzhose mit Klebestreifen oder Pants, sachgerecht verwenden, nach Bedarf wechseln und entsorgen. Dazu gehört auch die Anwendung eines Analtampons oder das Entleeren oder Wechseln eines Stomabeutels bei Enterostoma. Die Pflege des Stomas und der Wechsel einer Basisplatte sind unter F 4.5.9 zu berücksichtigen.", levels: ["Die Person kann Hilfsmittel selbständig benutzen.", "Die Person kann die Aktivität überwiegend selbständig durchführen, wenn Inkontinenzsysteme bereitgelegt und entsorgt werden oder die Person an den Wechsel erinnert wird.", "Die Person kann sich am Wechsel der Inkontinenzsysteme beteiligen, z. B. Mithilfe beim Wechsel eines Stomabeutels. Bei Vorliegen einer Stuhlinkontinenz sind Ressourcen beim Wechsel des Inkontinenzmaterials eher selten.", "Beteiligung ist nicht (oder nur minimal) möglich."] },
  "4.4.13": { definition: "Ernährung über einen parenteralen Zugang (z. B. einen Port) oder über einen Zugang in Magen oder Dünndarm (PEG/PEJ).", levels: ["Die Person führt die Versorgung ohne Fremdhilfe durch.", "Die Person erhält zusätzlich zur oralen Nahrungsaufnahme\nNahrung oder Flüssigkeit parenteral oder über\nSonde, aber nur gelegentlich oder vorübergehend.", "Die Person erhält in der Regel täglich Nahrung oder Flüssigkeit parenteral oder über Sonde und täglich oral Nahrung. Sie wird zum Teil, aber nicht ausreichend über die orale Nahrungsaufnahme ernährt und benötigt zur Nahrungsergänzung bzw. zur Vermeidung von Mangelernährung täglich Sondenkost.", "Die Person erhält ausschließlich oder nahezu ausschließlich Nahrung und Flüssigkeit parenteral oder über Sonde. Eine orale Nahrungsaufnahme erfolgt nicht oder nur in geringem Maße zur Förderung der Sinneswahrnehmung."] },
  "4.5.1": { definition: "Orale Medikation, Augen- oder Ohrentropfen, Zäpfchen und Medikamentenpflaster.\n\nDas Ausmaß der Hilfestellung kann von einmal wöchentlichem Stellen der Medikamente im Wochendispenser bis zu mehrfach täglicher Einzelgabe differieren. Werden Medikamente verabreicht, ist das Stellen nicht gesondert zu berücksichtigen." },
  "4.5.2": { definition: "Subkutane und intramuskuläre Injektionen und subkutane Infusionen\n\nDazu gehören z. B. Insulin-Injektionen oder auch die Versorgung mit Medikamentenpumpen über einen subkutanen Zugang." },
  "4.5.3": { definition: "Hierunter fällt hauptsächlich die Port-Versorgung. Sie ist oft fachpflegerisch erforderlich. In Bezug auf den Umgang mit intravenösen Zugängen ist auch die Kontrolle zur Vermeidung von Komplikationen wie Verstopfung des Katheters zu berücksichtigen. Analog ist auch die Versorgung intrathekaler Zugänge hier zu erfassen. Das Anhängen von Nährlösungen zur parenteralen Ernährung ist nicht hier, sondern unter Punkt F 4.4.13 zu erfassen." },
  "4.5.4": { definition: "Absaugen kann z. B. bei beatmeten oder tracheotomierten Patienten in sehr unterschiedlicher und wechselnder Häufigkeit notwendig sein. Es ist der durchschnittliche Bedarf anzugeben. Ebenso ist hier das An- und Ablegen von Sauerstoffbrillen oder analog auch von Atemmasken zur nächtlichen Druckbeatmung zu erfassen sowie das Bereitstellen eines Inhalationsgerätes (inkl. deren Reinigung). Jede Maßnahme ist auch einzeln zu berücksichtigen." },
  "4.5.5": { definition: "Hier sind alle externen Anwendungen mit ärztlich angeordneten Salben, Cremes, Emulsionen etc. abzubilden, außerdem Kälte- und Wärmeanwendungen, die z. B. bei rheumatischen Erkrankungen angeordnet werden. Jede Maßnahme ist auch einzeln zu berücksichtigen." },
  "4.5.6": { definition: "Die Aktivität umfasst Messungen wie z. B. Blutdruck, Puls, Blutzucker, Temperatur, Körpergewicht, Flüssigkeitshaushalt, soweit diese auf ärztliche Anordnung erfolgen. Dabei geht es nicht nur darum, die Messung durchzuführen, sondern auch notwendige Schlüsse zu ziehen, etwa zur Festlegung der erforderlichen Insulindosis oder zur Notwendigkeit anderer Maßnahmen, wie das Umstellen der Ernährung oder auch das Aufsuchen einer Ärztin oder eines Arztes. Dies gilt beispielsweise auch für Menschen mit erhöhtem Blutdruck, die zur Ergänzung der medikamentösen Therapie und einer Umstellung ihres Lebensstils regelmäßig Blutdruck und Puls kontrollieren." },
  "4.5.7": { definition: "Hierunter versteht man beispielsweise das An- und Ablegen von Prothesen, kieferorthopädischen Apparaturen; Orthesen, Brille, Hörgerät oder Kompressionsstrümpfen (inkl. deren Reinigung). Der Umgang mit Zahnprothesen ist unter Punkt F 4.4.2 zu erfassen." },
  "4.5.8": { definition: "Die Aktivität beinhaltet die Versorgung chronischer Wunden, wie z. B. Ulcus cruris oder Dekubitus." },
  "4.5.9": { definition: "Gemeint ist hier die Pflege künstlicher Körperöffnungen wie Tracheostoma, PEG, suprapubischer Blasenkatheter, Urostoma, Colo- oder Ileostoma. Hierbei ist auch das Reinigen des Katheters, die Desinfektion der Einstichstelle der PEG und falls notwendig auch der Verbandswechsel zu bewerten. Die Pflege eines Urostoma, Colo- oder Ileostoma ist in der Regel mit dem Wechsel der Basisplatte oder dem Wechsel eines einteiligen Systems verbunden. Der einfache Wechsel oder das Entleeren eines Stoma- oder Katheterbeutels oder das Anhängen von Sondennahrung sind unter den Punkten F 4.4.11 ff. zu werten." },
  "4.5.10": { definition: "Regelmäßige Einmalkatheterisierungen kommen insbesondere bei neurogenen  Blasenentleerungsstörungen vor. Mit Abführmethoden sind Anwendungen von Klistier, Einlauf, digitale Ausräumung gemeint." },
  "4.5.11": { definition: "Bei vielen Erkrankungen werden aus einer Heilmitteltherapie heraus Anweisungen zu einem Eigenübungsprogramm gegeben, welches dauerhaft und regelmäßig durchgeführt werden soll, z. B. krankengymnastische Übungen, Atemübungen oder logopädische Übungen. Des Weiteren sind Maßnahmen zur Sekretelimination (ausgenommen Absaugen) zu nennen oder die Durchführung spezifischer Therapien nach Bobath oder Vojta oder die Durchführung ambulanter Peritonealdialyse (CAPD)." },
  "4.5.12": { definition: "Gemeint sind hier spezielle Therapiemaßnahmen wie Hämodialyse oder Beatmung, die im häuslichen Umfeld durchgeführt werden können, wenn ständige Überwachung während der Maßnahme durch geschulte Pflegepersonen gewährleistet wird.\n\nSpezielle Krankenbeobachtung (gemäß Pos. 24 HKP-Richtlinie) ist meist rund um die Uhr erforderlich, z. B. bei maschineller Beatmung, und ist mit einmal täglich einzutragen." },
  "4.5.13": { definition: "Hierunter fallen regelmäßige Besuche bei der niedergelassenen Hausärztin bzw. beim niedergelassenen Hausarzt oder Fachärztin bzw. Facharzt zu diagnostischen oder therapeutischen Zwecken.\nWenn eine Unterstützung auf dem Weg zu oder bei Arztbesuchen erforderlich ist, ist diese in durchschnittlicher Häufigkeit zu erfassen." },
  "4.5.14": { definition: "Hier ist das Aufsuchen anderer Therapeuten, z. B. Physiotherapeuten/Krankengy nasten, Ergotherapeuten, Logopäden, Psychotherapeuten, von Krankenhäusern zur ambulanten Behandlung oder Diagnostik oder anderer Einrichtungen des Gesundheitswesens zu berücksichtigen.\n\nSollte der Gesamtzeitaufwand bei der Nutzung dieser Einrichtungen einschließlich der Fahrtzeiten für die Pflegeperson mehr als drei Stunden umfassen, so ist dies unter Punkt F 4.5.15 zu berücksichtigen." },
  "4.5.15": { definition: "Bei manchen Erkrankungen kann es notwendig sein, spezialisierte Einrichtungen aufzusuchen, wodurch erhebliche Fahrtzeiten anfallen können. Auch kann es erforderlich sein, sich zeitaufwendiger diagnostischer oder therapeutischer Maßnahmen zu unterziehen, z. B. onkologische Behandlung oder Dialyse. Der dafür erforderliche Zeitaufwand für die Pflegeperson muss pro Termin mehr als drei Stunden betragen. Sollte der Zeitaufwand bei der Nutzung dieser Einrichtungen (einschl. Fahrtzeiten) unter drei Stunden liegen, so ist dies unter Punkt F 4.5.13 oder F 4.5.14 zu berücksichtigen." },
  "4.6.1": { definition: "Den Tagesablauf nach individuellen Gewohnheiten und Vorlieben einteilen und bewusst gestalten und ggf. an äußere Veränderungen anpassen Dies erfordert planerische Fähigkeiten zur Umsetzung von Alltagsroutinen. Zu beurteilen ist, ob die Person von sich aus festlegen kann, ob und welche Aktivitäten sie im Laufe des Tages durchführen möchte, z. B. wann sie baden, essen oder zu Bett gehen oder wann sie fernsehen oder spazieren gehen möchte. Solche Festlegungen setzen voraus, dass die zeitliche Orientierung zumindest teilweise erhalten ist. Die Gutachterin bzw. der Gutachter kann dies prüfen, indem er sich z. B. den bisherigen oder künftigen Tagesablauf schildern lässt.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe\ndurchführen.", "Die Routineabläufe können weitgehend selbständig gestaltet werden, bei ungewohnten Veränderungen ist Unterstützung notwendig. Es reichen z. B. Erinnerungshilfen an einzelne vereinbarte Termine. Überwiegend selbständig ist eine Person beispielsweise auch dann, wenn ihre Kommunikationsfähigkeit oder Sinneswahrnehmung stark beeinträchtigt ist und sie daher Hilfe benötigt, um den Tagesablauf mit anderen Menschen abzustimmen.", "Die Person benötigt Hilfe beim Planen des Routinetagesablaufs. Sie ist aber in der Lage, Zustimmung oder Ablehnung zu Strukturierungsangeboten zu signalisieren. Sie kann eigene Planungen häufig nicht einhalten, da diese wieder vergessen werden. Deshalb ist über den ganzen Tag hinweg eine Erinnerung bzw. Aufforderung erforderlich. Überwiegend unselbständig ist auch eine Person, die zwar selbst planen und entscheiden kann, aber für jegliche Umsetzung personelle Hilfe benötigt.", "Mitwirkung an der Tagesstrukturierung oder Orientierung an vorgegebenen Strukturen ist nicht oder nur minimal möglich."] },
  "4.6.2": { definition: "Nach individuellen Gewohnheiten einen Tag-Nacht-Rhythmus einhalten und für ausreichende Ruhe- und Schlafphasen sorgen. Dazu gehört die Fähigkeit, die Notwendigkeit von Ruhephasen zu erkennen, sich auszuruhen und mit Phasen der Schlaflosigkeit umzugehen, aber auch die körperliche Fähigkeit, ins Bett zu kommen und die Ruhephasen insbesondere nachts einhalten zu können.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe\ndurchführen.", "Die Person benötigt personelle Hilfe beim Aufstehen oder Zu-Bett-Gehen, z. B. Transferhilfen oder zeitliche Orientierungshilfen beim Wecken oder Aufforderung, schlafen zu gehen, oder einzelne Hilfen wie z. B. Abdunkeln des Schlafraumes. Die Nachtruhe ist meist ungestört, nur gelegentlich entsteht nachts ein Hilfebedarf.", "Es treten regelmäßig Einschlafprobleme oder nächtliche Unruhe\nauf, die die Person größtenteils nicht allein bewältigen kann. Deshalb sind regelmäßige Einschlafrituale und beruhigende Ansprache in der Nacht erforderlich. Überwiegend unselbständig ist auch eine Person, die wegen hochgradiger motorischer Beeinträchtigung regelmäßig in der Nacht personeller Hilfe bedarf, um weiterschlafen zu können, z. B. bei Lagewechsel oder Toilettengängen in der Nacht.", "Die Person verfügt über keinen oder einen gestörten Schlaf-Wach-Rhythmus. Dies gilt u. a. für mobile gerontopsychiatrisch erkrankte Personen und auch für Menschen, die keinerlei Aktivitäten ausüben (z. B. Wachkoma-Patienten) oder Personen, die regelmäßig mindestens dreimal in der Nacht personelle Unterstützung benötigen."] },
  "4.6.3": { definition: "Die verfügbare Zeit nutzen, um Aktivitäten durchzuführen, die den eigenen Vorlieben und Interessen entsprechen\n\n„Verfügbare Zeit“ ist in diesem Zusammenhang definiert als Zeit, die nicht durch Notwendigkeiten wie Ruhen, Schlafen, Essen, Mahlzeitenzubereitung, Körperpflege, Arbeit etc. gebunden ist („freie“ Zeit).\n\nBei der Beurteilung geht es vorrangig um die Fähigkeit, nach individuellen kognitiven, manuellen, visuellen oder auditiven Fähigkeiten und Bedürfnissen geeignete Aktivitäten der Freizeitbeschäftigung auszuwählen und auch praktisch durchzuführen, z. B. Handarbeiten, Basteln, Bücher oder Zeitschriften lesen, Sendungen im Radio oder Fernsehen verfolgen, Computer nutzen. Dies gilt auch für Personen, die Angebote auswählen und steuern können, aber aufgrund somatischer Einschränkungen für die praktische Durchführung personelle Unterstützung benötigen.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe\ndurchführen.", "Es ist nur in geringem Maße Hilfe erforderlich, z. B. Zurechtlegen und Richten von Gegenständen, z. B. Utensilien wie Bastelmaterial, Fernbedienung, Kopfhörer o. Ä. oder Erinnerung an gewohnte Aktivitäten, Motivation oder Unterstützung bei der Entscheidungsfindung (Vorschläge unterbreiten).", "Die Person kann sich an Beschäftigungen beteiligen, aber nur mit (kontinuierlicher) Anleitung, Begleitung oder motorischer Unterstützung.", "Die Person kann an der Entscheidung oder Durchführung nicht nennenswert mitwirken. Sie zeigt keine Eigeninitiative, kann Anleitungen und Aufforderungen nicht kognitiv umsetzen, beteiligt sich nicht oder nur minimal an angebotenen Beschäftigungen."] },
  "4.6.4": { definition: "Längere Zeitabschnitte überschauend über den Tag hinausplanen\n\nDies kann beispielsweise anhand der Frage beurteilt werden, ob Vorstellungen oder Wünsche zu anstehenden Festlichkeiten wie Geburtstag oder Jahresfeste bestehen, ob die Zeitabläufe eingeschätzt werden können, z. B. vorgegebene Strukturen wie regelmäßige Termine nachvollzogen werden können, oder ob die körperlichen Fähigkeiten vorhanden sind, um eigene Zukunftsplanungen mit anderen Menschen kommunizieren zu können. Es ist auch zu berücksichtigen, wenn stark ausgeprägte psychische Problemlagen (z. B. Ängste) es verhindern, sich mit Fragen des zukünftigen Handelns auseinanderzusetzen.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe\ndurchführen.", "Die Person nimmt sich etwas vor, muss aber erinnert werden, dies auch durchzuführen. Oder sie benötigt infolge körperlicher Beeinträchtigungen regelmäßig Hilfe im Bereich der Kommunikation, um sich mit anderen Menschen verabreden zu können.", "Die Person plant von sich aus nicht, entscheidet aber mit Unterstützung durch andere Personen. Sie muss an die Umsetzung der eigenen Entscheidungen erinnert werden oder benötigt bei der Umsetzung emotionale oder körperliche Unterstützung. Überwiegend unselbständig ist daher auch eine Person, die zwar kognitiv in der Lage ist, selbständig zu planen und zu entscheiden, aber so stark somatisch beeinträchtigt ist, dass sie für alle Umsetzungsschritte personelle Hilfe benötigt.", "Die Person verfügt nicht über Zeitvorstellungen für Planungen über den Tag hinaus, auch bei Vorgabe von Auswahloptionen wird weder Zustimmung noch Ablehnung signalisiert."] },
  "4.6.5": { definition: "Im direkten Kontakt mit Angehörigen, Pflegepersonen, Mitbewohnern oder Besuchern umgehen, Kontakt aufnehmen, Personen ansprechen, auf Ansprache reagieren.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe\ndurchführen.", "Umgang mit bekannten Personen erfolgt selbständig, zur Kontaktaufnahme mit Fremden ist Unterstützung erforderlich, z. B. Anregung, zu einer neuen Mitbewohnerin oder einem neuen Mitbewohner Kontakt aufzunehmen oder punktuelle Unterstützung bei der Überwindung von Sprech-, Sprach- und Hörproblemen.", "Die Person ergreift von sich aus kaum Initiative. Sie muss angesprochen oder motiviert werden, reagiert aber verbal oder deutlich erkennbar durch andere Formen der Kommunikation (Blickkontakt, Mimik, Gestik). Überwiegend unselbständig ist auch eine Person, die auf weitgehende Unterstützung bei der Überwindung von Sprech-, Sprach- oder Hörproblemen angewiesen ist.", "Die Person reagiert nicht auf Ansprache. Auch nonverbale Kontaktversuche, z. B. Berührungen, führen zu keiner nennenswerten Reaktion."] },
  "4.6.6": { definition: "Bestehende Kontakte zu Freunden, Bekannten, Nachbarn aufrechterhalten, beenden oder zeitweise ablehnen Dazu gehört auch die Fähigkeit, mit technischen Kommunikationsmitteln wie Telefon umgehen zu können, z. B. Besuche verabreden oder Telefon- oder Brief- oder Mail-Kontakte.", levels: ["Die Person kann die beschriebene Aktivität ohne personelle Hilfe\ndurchführen.", "Die Person kann planen, braucht aber Hilfe beim Umsetzen wie z. B.  rinnerungszettel bereitlegen oder Telefonnummern mit Namen oder mit Bild versehen, Erinnern und Nachfragen, ob Kontakt hergestellt wurde, oder Erinnern an Terminabsprachen. Pflegeperson wählt die Telefonnummer, die Person führt dann das Gespräch; oder die Person beauftragt die Pflegeperson, ein Treffen mit Freunden, Bekannten zu verabreden.", "Die Kontaktgestaltung der Person ist eher reaktiv. Sie sucht von sich aus kaum Kontakt, wirkt aber mit, wenn beispielsweise die Pflegeperson die Initiative ergreift. Überwiegend unselbständig ist auch, wer aufgrund von somatischen Beeinträchtigungen während der Kontaktaufnahme personelle Unterstützung durch die Bezugsperson, z. B. bei der Nutzung von Kommunikationshilfen (Telefon halten) oder bei der Überwindung von Sprech-, Sprach- oder Hörproblemen, benötigt.", "Die Person nimmt keinen Kontakt außerhalb des direkten Umfeldes auf und reagiert nicht auf Anregungen zur Kontaktaufnahme."] },
  "diaet": { definition: "Bei manchen Erkrankungen werden bestimmte Diäten11 oder Essvorschriften oder andere Verhaltensvorschriften von der Ärztin oder vom Arzt angeordnet. Dazu gehören auch die ärztlich angeordnete Nahrungs- und Flüssigkeitszufuhr, in der sowohl die Art und Menge der Lebensmittel wie auch die Art und der Zeitpunkt der Aufnahme aus therapeutischen Gründen geregelt sind, z. B. bei Stoffwechselstörungen, Nahrungsmittelallergien, bei Essstörungen wie Anorexie oder Prader-Willi-Syndrom. Andere Verhaltensvorschriften können sich auf vitale Funktionen beziehen, z. B. Sicherstellung einer Langzeit-Sauerstoff-Therapie bei unruhigen Personen.\nDiese Vorschriften sind im Einzelnen zu benennen. Im Weiteren sind der Grad der Selbständigkeit bei der Einhaltung dieser Vorschriften und der daraus resultierende Bedarf an personeller Unterstützung zu beurteilen. Es geht hier um die Einsichtsfähigkeit der Person zur Einhaltung der Vorschriften und nicht um die Zubereitung einer Diät oder das An- und Ablegen einer Sauerstoffmaske.\nNicht gemeint ist die selbstbestimmte Ablehnung von ärztlichen Vorschriften bei erhaltenen mentalen Funktionen.\nLiegen keine Vorschriften vor, ist das Feld „entfällt, nicht erforderlich“ anzukreuzen." },
};

export const BESONDERE_BEDARFSKONSTELLATION_EXPLANATION =
  "Gemäß § 15 Abs. 4 SGB XI können Pflegebedürftige mit besonderen Bedarfskonstellationen, die einen spezifischen, außergewöhnlich hohen Hilfebedarf mit besonderen Anforderungen an die pflegerische Versorgung aufweisen, aus pflegefachlichen Gründen dem Pflegegrad 5 zugeordnet werden, auch wenn ihre Gesamtpunkte unter 90 liegen.\n\nIn Betracht kommen Pflegebedürftige, die rein nach Punkten den Pflegegrad 5 nicht erreichen würden, dieser aber aufgrund der Schwere der Beeinträchtigung angemessen wäre. Als besondere Bedarfskonstellation ist nur die Gebrauchsunfähigkeit beider Arme und beider Beine festgelegt.\nHintergrund ist, dass die jeweiligen gesundheitlichen Probleme sich einer pflegefachlichen Systematisierung im neuen Begutachtungsinstrument entziehen. Trotz vollständiger Abhängigkeit von personeller Hilfe ist es möglich, dass bei diesem Personenkreis im Bereich der Module 2 und 3 keine und im Bereich des Moduls 6 Beeinträchtigungen nur im geringen Maß vorliegen, so dass die Gesamtpunkte unter 90 liegen.\n\nVollständiger Verlust der Greif-, Steh- und Gehfunktionen\n\nDas Kriterium der „Gebrauchsunfähigkeit beider Arme und beider Beine“ umfasst nicht zwingend die Bewegungsunfähigkeit der Arme und Beine, die durch Lähmungen aller Extremitäten hervorgerufen werden kann. Ein vollständiger Verlust der Greif-, Steh- und Gehfunktion ist unabhängig von der Ursache zu bewerten. Dies kann z. B. auch bei Menschen im Wachkoma vorkommen oder durch hochgradige Kontrakturen, Versteifungen, hochgradigen Tremor und Rigor oder Athetose bedingt sein.\nEine Gebrauchsunfähigkeit beider Arme und beider Beine liegt auch vor, wenn eine minimale Restbeweglichkeit der Arme noch vorhanden ist, z. B. die Person mit dem Ellenbogen noch den Joystick eines Rollstuhls bedienen kann, oder nur noch unkontrollierbare Greifreflexe bestehen.";
